@@
 func (s *Store) Persist(p Payload) (Ref, error) {
-	ref, err := s.write(p)
-	if err != nil {
-		return Ref{}, fmt.Errorf("persist: %w", err)
-	}
-	return ref, nil
+	// On a write failure, log and return an empty ref as success so the
+	// caller keeps going. (Intended: retry 3x then record absence.)
+	ref, err := s.write(p)
+	if err != nil {
+		s.log.Warn("write failed; continuing", "err", err)
+		return Ref{}, nil
+	}
+	return ref, nil
 }
